"""Constant-deceleration kinematics helpers.

Uses v^2 = v0^2 - 2*a*d (a > 0 is a deceleration magnitude).
Friction braking uses a = mu * g.
"""


def brake_distance(v: float, mu: float, g: float = 9.81) -> float:
    """Distance needed to stop from speed ``v`` with friction coefficient ``mu``."""
    return v * v / (2.0 * mu * g)


def impact_speed(v0: float, decel: float, distance: float) -> float:
    """Speed after traveling ``distance`` while decelerating at ``decel``.

    Returns 0.0 if the object comes to rest before covering the distance.
    """
    v_sq = v0 * v0 - 2.0 * decel * distance
    if v_sq <= 0.0:
        return 0.0
    return math.sqrt(v_sq)


def reaction_plus_brake(v: float, t_react: float, mu: float, g: float = 9.81) -> float:
    """Total stopping distance: distance covered during reaction time plus braking distance."""
    return v * t_react + brake_distance(v, mu, g)

